interface PricingConfig {
  basePrices: Record<string, number>;
  taxRate: number;
  processingFeeRate: number;
}

const PRICING_CONFIG: PricingConfig = {
  basePrices: { premium: 9.99, enterprise: 49.99 },
  taxRate: 0.08,
  processingFeeRate: 0.029
};

function calculateSubscriptionPrice(
  tier: 'premium' | 'enterprise',
  config = PRICING_CONFIG
): number {
  const basePrice = config.basePrices[tier];
  const tax = basePrice * config.taxRate;
  const fee = basePrice * config.processingFeeRate;
  return basePrice + tax + fee;
}

